    "credit": "Pawel Czerwinski",
    "license": "Unsplash",
    "link": "https://unsplash.com/photos/blue-and-white-tablet-in-container-2Y8ol_OBS1I?utm_source=dia_news&utm_medium=referral",
    "alt": "blue and white tablet in container"
